class DetectSquares {
    unordered_map<int, unordered_map<int, int>> cnt;
public:
    DetectSquares() {

    }

    void add(vector<int> point) {
        cnt[point[0]][point[1]]++;
    }

    int count(vector<int> point) {
        int x = point[0], y = point[1];
        long long res = 0;
        for (auto& [px, row] : cnt) {
            if (px == x) continue;
            for (auto& [py, c1] : row) {
                if (py == y) continue;
                if (abs(px - x) != abs(py - y)) continue;
                int c2 = 0, c3 = 0;
                auto it = cnt.find(x);
                if (it != cnt.end()) {
                    auto it2 = it->second.find(py);
                    if (it2 != it->second.end()) c2 = it2->second;
                }
                auto it3 = row.find(y);
                if (it3 != row.end()) c3 = it3->second;
                res += (long long)c1 * c2 * c3;
            }
        }
        return (int)res;
    }
};
